def update_frames(te: traceback.TracebackException) -> None:
    # Update line numbers and add source code to frames
    for i, frame in enumerate(te.stack):
        try:
            source_lines, line_offset = self.source_cache[frame.filename]
        except KeyError:
            continue
        # The cached source is the compilable source, so we need to look
        # the line up with the original (unadjusted) line number.
        # Adjust the line index (lineno is 1-based, list indices are 0-based)
        line_index = frame.lineno - 1
        line = None
        if 0 <= line_index < len(source_lines):
            line = source_lines[line_index].rstrip("\n")
        # Adjust line number by the source line offset
        lineno = frame.lineno - line_offset
        te.stack[i] = traceback.FrameSummary(
            frame.filename, lineno, frame.name, line=line
        )
